"""Additional developer-reviewed notes from supplied corpus, never test answers.

Only the compiled JSON is shipped. Each fact must have visible source anchors.
Optional question patterns select a note, never supply facts or system text.
"""

def note(topic, selectors, hint, when='', priority=1):
    return ([topic] if isinstance(topic,str) else topic,selectors,hint,
            {'when':when,'priority':priority})


